<?php
namespace App\Http\Controllers;
use App\Services\Store;
use App\Services\Totp;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\Crypt;
use Illuminate\Support\Facades\Storage;
use Illuminate\Support\Str;
class StoreController extends Controller {
 public function __construct(private Store $store){}
 public function catalog(Request $r){return ['products'=>$this->store->catalog(),'settings'=>$this->store->settings(),'admin'=>(bool)$r->user()?->is_admin];}
 private function input(Request $r,bool $full=false):array {foreach(['mobile','postal']as $field)if($r->has($field)&&is_string($r->input($field)))$r->merge([$field=>strtr($r->input($field),array_combine(preg_split('//u','۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩',-1,PREG_SPLIT_NO_EMPTY),str_split('01234567890123456789')))]);$rules=['items'=>'required|array|min:1|max:50','items.*.variant_id'=>'required|integer|min:1','items.*.quantity'=>'required|integer|min:1|max:99','province'=>'required|string|max:60'];if($full)$rules+=['name'=>'required|string|min:2|max:120','mobile'=>'required|string|regex:/^09[0-9]{9}$/','city'=>'required|string|max:60','address'=>'required|string|min:10|max:600','postal'=>'required|string|regex:/^[0-9]{10}$/','email'=>'nullable|email|max:200','note'=>'nullable|string|max:500','idempotency_key'=>'required|uuid','quote_signature'=>'required|string|size:64'];$validated=$r->validate($rules);if($full){$locations=config('iran_locations',[]);if(!isset($locations[$validated['province']])||!in_array($validated['city'],$locations[$validated['province']],true))throw \Illuminate\Validation\ValidationException::withMessages(['city'=>'استان و شهر انتخاب‌شده معتبر نیست.']);}return $validated;}
 public function quote(Request $r){$q=$this->store->quote($this->input($r));$q['signature']=$this->store->signature($q,$r->session()->getId());return $q;}
 public function checkout(Request $r){$input=$this->input($r,true);if(!config('maro.live')&&config('maro.gateway')==='zarinpal'&&!config('maro.sandbox'))Store::fail('پرداخت واقعی غیرفعال است.');return $this->store->start($input,$r->session()->getId());}
 public function track(Request $r){$r->validate(['token'=>'required|string|regex:/^[a-f0-9]{64}$/']);$o=DB::table('orders')->where('token_hash',hash('sha256',$r->input('token')))->first();abort_unless($o,404);return ['number'=>$o->number,'payment_status'=>$o->payment_status,'fulfillment_status'=>$o->fulfillment_status,'total'=>(int)$o->total,'items'=>DB::table('order_items')->where('order_id',$o->id)->get(['name','variant_label','quantity','unit_price']),'shipment'=>DB::table('shipments')->where('order_id',$o->id)->first(['carrier','tracking_code','shipped_at'])];}
 public function callback(Request $r){$authority=$r->query('Authority');abort_unless(is_string($authority)&&strlen($authority)<=150,400);$a=DB::table('payment_attempts')->where('authority',$authority)->first();abort_unless($a,404);$status=$this->store->reconcile($a->id);return response()->view('payment',['status'=>$status]);}
 public function login(Request $r){$r->validate(['email'=>'required|email','password'=>'required|string','totp'=>'nullable|string|max:6']);$u=\App\Models\User::where('email',$r->email)->first();if(!$u||!$u->is_admin||!Hash::check($r->password,$u->password))Store::fail('اطلاعات ورود صحیح نیست.');if($u->totp_secret){$valid=DB::transaction(function()use($u,$r){$locked=DB::table('users')->where('id',$u->id)->lockForUpdate()->first();$counter=Totp::counter(Crypt::decryptString($locked->totp_secret),(string)$r->totp,$locked->totp_last_counter);if($counter===null)return false;DB::table('users')->where('id',$u->id)->update(['totp_last_counter'=>$counter]);return true;});if(!$valid)Store::fail('کد تأیید صحیح نیست یا قبلاً استفاده شده است.');}Auth::login($u);$r->session()->regenerate();return ['ok'=>true];}
 public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return ['ok'=>true];}
 public function products(){return $this->store->catalog(true);}
 private function audit(Request $r,string $event,string $subject,array $metadata=[]){DB::table('audit_logs')->insert(['admin_id'=>$r->user()->id,'event'=>$event,'subject'=>$subject,'metadata'=>json_encode($metadata),'created_at'=>now(),'updated_at'=>now()]);}
 public function saveProduct(Request $r,?int $id=null){$r->merge(['variants'=>json_decode(is_string($r->input('variants'))?$r->input('variants'):'null',true)]);$d=$r->validate(['name'=>'required|string|max:120','description'=>'nullable|string|max:2000','specifications'=>'nullable|string|max:2000','category'=>'required|string|max:60','status'=>'required|in:draft,published,archived','featured'=>'required|boolean','reason'=>'required|string|max:250','variants'=>'required|array|min:1|max:100','variants.*.id'=>'nullable|integer','variants.*.revision'=>'nullable|integer|min:0','variants.*.color'=>'required|string|max:50','variants.*.size'=>'required|string|max:50','variants.*.price'=>'required|integer|min:10|max:100000000000|multiple_of:10','variants.*.stock'=>'required|integer|min:0|max:100000','variants.*.published'=>'required|boolean','variants.*.sale_enabled'=>'sometimes|boolean','variants.*.sku'=>'required|string|max:100','images'=>'nullable|array|max:10','images.*'=>'file|image|mimes:jpeg,png,webp|max:5120|dimensions:max_width=6000,max_height=6000']);
 // Re-encode uploads into inert raster files; original files are never publicly served.
 $uploads=[];foreach($r->file('images',[])as $file){$info=@getimagesize($file->getRealPath());if(!$info||!in_array($info['mime'],['image/jpeg','image/png','image/webp'])||$info[0]*$info[1]>24000000)Store::fail('ابعاد یا نوع تصویر مجاز نیست.');$im=@imagecreatefromstring(file_get_contents($file->getRealPath()));if(!$im)Store::fail('تصویر معتبر نیست.');$w=imagesx($im);$h=imagesy($im);$scale=min(1,1200/max($w,$h));$small=imagecreatetruecolor((int)round($w*$scale),(int)round($h*$scale));imagealphablending($small,false);imagesavealpha($small,true);imagecopyresampled($small,$im,0,0,0,0,imagesx($small),imagesy($small),$w,$h);$name=Str::uuid().'.webp';$path='uploads/'.$name;Storage::disk('local')->makeDirectory('uploads');imagewebp($small,Storage::disk('local')->path($path),88);imagedestroy($im);imagedestroy($small);$original=$file->storeAs('originals',Str::uuid().'.bin','local');$uploads[]=['path'=>$path,'original_path'=>$original];}
 try{$id=DB::transaction(function()use($id,$d,$r,$uploads){if($id)abort_unless(DB::table('products')->where('id',$id)->lockForUpdate()->first(),404);$category=DB::table('categories')->where('name',$d['category'])->value('id')??DB::table('categories')->insertGetId(['name'=>$d['category'],'created_at'=>now(),'updated_at'=>now()]);$values=['name'=>$d['name'],'description'=>$d['description'],'specifications'=>$d['specifications']??null,'category_id'=>$category,'status'=>$d['status'],'featured'=>$d['featured'],'updated_at'=>now()];if($id)DB::table('products')->where('id',$id)->update($values);else $id=DB::table('products')->insertGetId($values+['slug'=>'maro-'.strtolower(Str::random(12)),'created_at'=>now()]);$retained=[];
 foreach($d['variants']as $v){$existing=isset($v['id'])?DB::table('product_variants')->where('id',$v['id'])->where('product_id',$id)->lockForUpdate()->first():null;$vals=['product_id'=>$id,'sku'=>$v['sku'],'color'=>$v['color'],'size'=>$v['size'],'price'=>$v['price'],'stock'=>$v['stock'],'published'=>true,'sale_enabled'=>$v['sale_enabled']??true,'updated_at'=>now()];if(!$existing&&!empty($v['id']))Store::fail('تنوع انتخاب‌شده متعلق به این محصول نیست.');if($existing){if(!isset($v['revision'])||(int)$v['revision']!==(int)$existing->revision)Store::fail('این تنوع از زمان بازکردن فرم تغییر کرده؛ صفحه را تازه کنید تا موجودی جدید بازنویسی نشود.');$vals['revision']=$existing->revision+1;$reserved=DB::table('inventory_reservations')->where('variant_id',$existing->id)->where('status','active')->where('expires_at','>',now())->sum('quantity');if($v['stock']<$reserved)Store::fail('موجودی کمتر از رزروهای فعال نمی‌تواند باشد.');DB::table('product_variants')->where('id',$existing->id)->update($vals);$vid=$existing->id;$delta=$v['stock']-$existing->stock;}else{$vid=DB::table('product_variants')->insertGetId($vals+['created_at'=>now()]);$delta=$v['stock'];}$retained[]=$vid;if($delta!==0)DB::table('stock_movements')->insert(['variant_id'=>$vid,'admin_id'=>$r->user()->id,'quantity'=>$delta,'event_key'=>'admin:'.Str::uuid(),'reason'=>$d['reason'],'created_at'=>now(),'updated_at'=>now()]);}
 DB::table('product_variants')->where('product_id',$id)->whereNotIn('id',$retained)->update(['published'=>false]);$pos=(int)DB::table('product_images')->where('product_id',$id)->max('position');foreach($uploads as $u)DB::table('product_images')->insert($u+['product_id'=>$id,'alt'=>$d['name'],'position'=>++$pos,'created_at'=>now(),'updated_at'=>now()]);$order=json_decode(is_string($r->input('image_order'))?$r->input('image_order'):'[]',true);if(is_array($order))foreach($order as $index=>$src){if(!is_string($src))continue;DB::table('product_images')->where('product_id',$id)->where(function($q)use($src){if(preg_match('#^/media/(\d+)$#',$src,$m))$q->where('id',(int)$m[1]);else $q->where('path',$src);})->update(['position'=>$index]);}$this->audit($r,'product.saved',(string)$id,['reason'=>$d['reason']]);return $id;},5);}catch(\Throwable $e){foreach($uploads as $u)Storage::disk('local')->delete([$u['path'],$u['original_path']]);throw $e;}return ['id'=>$id];}
 public function media(int $id){$image=DB::table('product_images')->find($id);abort_unless($image,404);$p=DB::table('products')->find($image->product_id);abort_unless($p->status==='published'||request()->user()?->is_admin,404);abort_if(str_starts_with($image->path,'assets/'),404);return response()->file(Storage::disk('local')->path($image->path),['Content-Type'=>'image/webp','X-Content-Type-Options'=>'nosniff','Cache-Control'=>'public,max-age=86400']);}
 public function settings(Request $r){$d=$r->validate(['about'=>'required|string|max:2000','shipping'=>'required|integer|min:0|max:100000000|multiple_of:10','free_above'=>'nullable|integer|min:0|max:100000000000|multiple_of:10','banner'=>'nullable|string|max:120','hero_image'=>['nullable','regex:#^(assets/|/media/)[a-zA-Z0-9_./-]+$#'],'contact'=>'nullable|string|max:4000','shipping_policy'=>'nullable|string|max:4000','returns_policy'=>'nullable|string|max:4000','privacy_policy'=>'nullable|string|max:4000','terms_policy'=>'nullable|string|max:4000','size_guide'=>'nullable|string|max:4000']);DB::transaction(function()use($r,$d){DB::table('site_settings')->updateOrInsert(['key'=>'about'],['value'=>$d['about'],'updated_at'=>now(),'created_at'=>now()]);DB::table('shipping_rules')->updateOrInsert(['province'=>null],['amount'=>$d['shipping'],'free_above'=>$d['free_above'],'enabled'=>true,'updated_at'=>now(),'created_at'=>now()]);foreach(['banner','hero_image','contact','shipping_policy','returns_policy','privacy_policy','terms_policy','size_guide']as $key)if(array_key_exists($key,$d))DB::table('site_settings')->updateOrInsert(['key'=>$key],['value'=>$d[$key],'updated_at'=>now(),'created_at'=>now()]);$this->audit($r,'settings.updated','store');});return ['ok'=>true];}
 public function stats(){return ['paid'=>DB::table('orders')->where('payment_status','paid')->count(),'sales'=>(int)DB::table('orders')->where('payment_status','paid')->sum('total'),'review'=>DB::table('orders')->whereIn('payment_status',['review','paid_exception'])->count()];}
 public function orders(){return DB::table('orders')->latest('id')->limit(200)->get(['id','number','total','payment_status','fulfillment_status','created_at']);}
 public function order(int $id){$o=DB::table('orders')->find($id);abort_unless($o,404);unset($o->token_encrypted,$o->token_hash,$o->owner_hash,$o->idempotency_key);$o->items=DB::table('order_items')->where('order_id',$id)->get();return $o;}
 public function shipment(Request $r,int $id){$d=$r->validate(['status'=>'required|in:processing,shipped,delivered','carrier'=>'required_if:status,shipped,delivered|nullable|string|max:100','tracking_code'=>'required_if:status,shipped,delivered|nullable|string|max:100','shipped_at'=>'required_if:status,shipped,delivered|nullable|date|before_or_equal:today']);DB::transaction(function()use($r,$id,$d){$o=DB::table('orders')->where('id',$id)->lockForUpdate()->first();abort_unless($o,404);if($o->payment_status!=='paid')Store::fail('سفارش بدون پرداخت تأییدشده قابل ارسال نیست.');$rank=['unfulfilled'=>0,'processing'=>1,'shipped'=>2,'delivered'=>3];if($rank[$d['status']]<$rank[$o->fulfillment_status])Store::fail('بازگشت وضعیت ارسال مجاز نیست.');DB::table('shipments')->updateOrInsert(['order_id'=>$id],['carrier'=>$d['carrier'],'tracking_code'=>$d['tracking_code'],'shipped_at'=>$d['shipped_at'],'created_at'=>now(),'updated_at'=>now()]);DB::table('orders')->where('id',$id)->update(['fulfillment_status'=>$d['status'],'updated_at'=>now()]);$this->audit($r,'shipment.updated',(string)$id,['status'=>$d['status']]);});return ['ok'=>true];}
}
